    e10: "ความประหลาดใจ ความเข้าใจใหม่ หรือการส่งสัญญาณเปลี่ยนหัวข้อ",
    e11: "เสียงสั้นขึ้นสูง \"Nå!\" (ประหลาดใจ ↗), เสียงยาว \"Nååh...\" (เข้าใจแล้ว ↘) หรือ \"Nå, men...\" (เปลี่ยนเรื่อง →)",
    e12: "ดูการวิเคราะห์วิดีโอ YouTube ฉบับเต็มเกี่ยวกับ 10 ความหมายของ \"Nå\" ในภาษาเดนมาร์กได้ที่แท็บ 4 (ห้องทดลองน้ำเสียง)!",
    e13: "การยืนยันและเห็นด้วย (คำว่า \"jaja\" อาจสื่อถึงความใจร้อนหรือการปลอบใจแบบเอ็นดูได้ด้วย)",
    e14: "เสียงนิ่งๆ \"Ja...\" (สนับสนุนให้พูดต่อ →) เทียบกับเสียงเร็ว \"Jaja!\" (ใจร้อน/ตัดบท)",
    e15: "อย่าพูด \"Ja-ja-ja!\" เร็วๆ สามครั้งติดกันเมื่อคนเดนมาร์กกำลังอธิบายอะไรให้คุณฟัง – มันจะถูกมองว่า \"พอแล้ว ไม่อยากฟังต่อแล้ว!\"",
    e16: "คำว่า \"ja\" สั้นๆ ที่เปล่งเสียงขณะสูดลมหายใจเข้า ใช้แสดงความเห็นพ้องอย่างเงียบๆ การรู้สึกตรงกัน หรือการครุ่นคิด",
    e17: "เสียงกระซิบแผ่วๆ มีลม \".hja\" ที่ดูดเข้าไปขณะสูดลมหายใจเข้า (หายใจเข้า ←)",
    e18: "ชาวต่างชาติมักนึกว่าคนเดนมาร์กกำลังหอบหรือเจ็บคอ – แต่จริงๆ แล้วมันคือคำว่า \"ja\" ที่อบอุ่นและนุ่มนวลที่สุดในภาษาเดนมาร์ก!",
    e19: "ความเข้าใจอย่างกะทันหัน หรือการตระหนักถึงความเชื่อมโยงใหม่",
    e20: "เสียงสองพยางค์ที่ยกสูงชัดเจนในพยางค์ที่สอง (a-HA! ↗↘)",
    e21: "\"Aha\" เน้นเรื่องเหตุผลและข้อเท็จจริงมากกว่า (\"ตอนนี้เข้าใจระบบแล้ว\") ส่วน \"Nåååh\" จะมีอารมณ์และความเห็นอกเห็นใจรวมอยู่ด้วย",
    e22: "ความประหลาดใจ ความไม่อยากเชื่อ หรือความเห็นอกเห็นใจ (เช่น \"nej, hvor ærgerligt\")",
    e23: "คำอุทานที่มีน้ำหนักและใส่อารมณ์เสียงลงแล้วขึ้น (\"Neeej!\" / \"Næh dog!\")",
    e24: "อย่าเพิ่งงงหากคนเดนมาร์กตอบว่า \"Neeej!\" พร้อมรอยยิ้มกว้างตอนคุณเล่าข่าวดี – มันแปลว่า \"โอ้โห เจ๋งและน่ายินดีมาก!\"",
    e25: "การคัดค้าน ความประหลาดใจ หรือการเน้นย้ำความรู้สึกตอบสนอง (\"ej, det mener du ikke\")",
    e26: "สระประสมสั้นหรือลากยาว [ɑj] พร้อมการเน้นอารมณ์อย่างชัดเจน",
    e27: "\"Ej\" มักอยู่คู่กับคำแสดงอารมณ์เสมอ เช่น \"Ej hvor godt\", \"Ej hvor sjovt\", \"Ej hvor irriterende\"",
    e28: "ความเห็นอกเห็นใจ ความโล่งใจ ความหงุดหงิด หรือความตื่นเต้นยินดี",
    e29: "เสียงสระยาว ทุ้ม และผ่อนลมหายใจออกอย่างนุ่มนวล (มีเสียง r ชัดเจนใน \"Årh\") ↘",
    e30: "เมื่อคนเดนมาร์กพูดว่า \"Årh, det skal du ikke tænke på!\" นั่นคือสัญญาณที่อบอุ่นและช่วยปลอบใจ",
