    x123: "ว้าย",
    x124: "Nadia: \"ดูสิ ตอนนี้ฉันวางชอร์ตคัตไว้บนหน้าจอให้ด้วยแล้ว ต่อไปจะได้คลิกแค่ทีเดียวพอ\"",
    x125: "อุ๊ย ขอบคุณมากเลยนะ Nadia! โอ้โห ช่วยได้เยอะมากจริงๆ!",
