    x127: "อะไรนะ?",
    x128: "Søren: \"ช่างสัญญาว่าจะมาตอน 8 โมงเช้า แล้วเพิ่งโทรมาตอนบ่าย 3 บอกว่าลืมนัด!\"",
    x129: "หาาา ไม่จริงน่า?! ชิ... แย่มากเลยนะแบบนี้!",
    x130: "อุ๊ย ดีจังเลย!",
    x131: "Søren: \"ใช่ เสียวันหยุดไปฟรีๆ ทั้งวันเลย! ว่าแต่คุณคิดว่าเราจะขอส่วนลดค่าจ้างได้ไหม?\"",
    x132: "ก็... คือว่า ถ้าคุณมีข้อตกลงเป็นลายลักษณ์อักษร ก็อาจจะลองถามหัวหน้าช่างดูได้นะ",
    x133: "อุ๊ย!",
    x134: "เฮ้อ!",
    x135: "Søren: \"ประเด็นดีเลย! เอาล่ะ แต่ดูสิใครโผล่หน้าออกมาจากตะกร้านี้ – วันนี้เราเพิ่งไปรับลูกหมาดัชชุนตัวใหม่มา!\"",
    x136: "โถ น่ารักจังเลย! ดูหูเล็กๆ นั่นสิ!",
    x137: "ว้าย!",
    x138: "ชิ",
    x139: "แบบไม่มีเสียงแทรกในบทสนทนา: \"ฉันเสร็จตอน ... 15.30 น. เวลานั้นสะดวกที่สุด\"",
    x140: "แบบมีเสียงแทรกภาษาเดนมาร์ก: \"ฉันเสร็จตอน... [1]... 15.30 น. [2] จริงๆ เวลานั้นสะดวกที่สุด\"",
    x141: "แบบไม่มีเสียงแทรกในบทสนทนา: A: \"เที่ยวบินของเราถูกยกเลิก\" — B: \"แย่จัง ฉันเสียใจด้วยนะ\"",
    x142: "แบบมีเสียงแทรกภาษาเดนมาร์ก: A: \"เที่ยวบินของเราถูกยกเลิก\" — B: \"[1] น่าเสียดายจัง! โธ่ [2] แทนพวกคุณเลย!\"",
    x143: "แบบไม่มีเสียงแทรกในบทสนทนา: A: \"ปุ่มอยู่ด้านหลัง\" — B: \"ตอนนี้เข้าใจแล้ว ฉันมองผิดด้าน\"",
    x144: "แบบมีเสียงแทรกภาษาเดนมาร์ก: A: \"ปุ่มอยู่ด้านหลัง\" — B: \"[1]! ตอนนี้เข้าใจแล้ว! [2] ฉันมัวแต่มองด้านหน้าอย่างเดียว!\"",
    x145: "แบบไม่มีเสียงแทรกในบทสนทนา: A: \"กระเบื้องหลังคาปลิวลงมาตอนพายุเข้า แต่ตอนนี้ฉันถึงบ้านแล้ว\" — B: \"อันตรายมากเลย\"",
    x146: "แบบมีเสียงแทรกภาษาเดนมาร์ก: A: \"[1] ในที่สุดก็เข้ามาในบ้านอุ่นๆ พ้นพายุเสียที!\" — B: \"[2] ฟังดูอันตรายมากเลยเรื่องกระเบื้องหลังคา!\"",
    x147: "แบบไม่มีเสียงแทรกในบทสนทนา: A: \"นี่ของขวัญสำหรับคุณ\" — B: \"ขอบคุณ ฉันดีใจ\"",
    x148: "แบบมีเสียงแทรกภาษาเดนมาร์ก: A: \"นี่ของขวัญสำหรับคุณ\" — B: \"[1] ขอบคุณมากเลย! [2] พวกคุณน่ารักกันจัง!\"",
    x149: "แบบไม่มีเสียงแทรกในบทสนทนา: A: \"วันนี้เรากินข้าวข้างนอกที่ระเบียงกันไหม?\" — B: \"ลมแรงมาก เรานั่งในห้องกระจกก็ได้\"",
    x150: "แบบมีเสียงแทรกภาษาเดนมาร์ก: A: \"วันนี้เรากินข้าวข้างนอกที่ระเบียงกันไหม?\" — B: \"[1]... ลมค่อนข้างแรงนะ [2] เรานั่งในห้องกระจกกันไม่ดีกว่าเหรอ?\"",
    x151: "แบบไม่มีเสียงแทรกในบทสนทนา: A: \"ฉันเจอนายกเทศมนตรีในลิฟต์...\" — B: \"ฉันฟังอยู่ น่าประหลาดใจมาก\"",
    x152: "แบบมีเสียงแทรกภาษาเดนมาร์ก: A: \"ฉันเจอนายกเทศมนตรีในลิฟต์...\" — B: \"[1]? [2]! แล้วเขาพูดว่าอะไรล่ะ?!\"",
    x153: "แบบไม่มีเสียงแทรกในบทสนทนา: A: \"เขาแซงคิวคุณยายไปเฉยเลย\" — B: \"คุณพูดเล่นใช่ไหม เป็นพฤติกรรมที่แย่มาก\"",
    x154: "แบบมีเสียงแทรกภาษาเดนมาร์ก: A: \"เขาแซงคิวคุณยายไปเฉยเลย\" — B: \"[1] ไม่จริงน่า?! [2] ไร้มารยาทจริงๆ!\"",
