    x217: "\"การเลื่อนประชุมเป็นไอเดียที่ดีมากเลย ใช่ไหม?\"",
    x218: "\"คือว่า ถ้าถามฉันนะ เราควรเริ่มจากบทที่ 2\"",
    x219: "\"อ๋อออ... มิน่าล่ะรถไฟถึงจอดนิ่งอยู่บนสะพาน!\"",
    x220: "\"เราต้องการ... เรียกว่าอะไรนะ... ปลั๊กพ่วง!\"",
    x221: "\"ใช่เลย! มันเป็นอย่างนั้นจริงๆ แหละ\"",
    x222: "\"เอาล่ะ... เราสั่งอาหารกันเลยไหม?\"",
    x223: "\"วันศุกร์นี้คุณไม่ได้ทำงานใช่ไหม?\"",
    x224: "\"จริงเหรอ?! เล่าต่อเร็วว่าเกิดอะไรขึ้นหลังจากนั้น!\"",
    x225: "\"จริงๆ แล้วร้านตรงนั้นจ่ายด้วย MobilePay ได้นะ\"",
    x226: "\"อ้าว จริงเหรอ! ไม่รู้มาก่อนเลย – ขอบคุณสำหรับคำแนะนำนะ\"",
    x227: "\"เมื่อไหร่เราตอบ JA และเมื่อไหร่เราตอบ JO ในภาษาเดนมาร์ก?\"",
    x228: "\"คืนนี้คุณจะมาไหม?\" → \"มา (Ja)\" หรือ \"ไม่มา (Nej)\"",
    x229: "\"คุณซื้อของเข้าบ้านหรือยัง?\" → \"ซื้อแล้ว (Ja)\" / \"ยังไม่ได้ซื้อ (Nej)\"",
    x230: "\"สุดสัปดาห์นี้คุณต้องทำงานไหม?\" → \"ต้องทำ (Ja)\" / \"ไม่ต้องทำ (Nej)\"",
    x231: "\"เมื่อมีคำว่า IKKE ในคำถาม เราจะตอบ ja ไม่ได้ – เราต้องตอบ JO หรือ NEJ!\"",
    x232: "\"คืนนี้คุณไม่มาเหรอ?\" → \"มาสิ ฉันมา! (Jo)\" หรือ \"ไม่ ฉันไม่มา (Nej)\"",
    x233: "\"คุณยังไม่ได้ซื้อของเหรอ?\" → \"ซื้อแล้วสิ ฉันซื้อแล้ว! (Jo)\" / \"ยัง ฉันยังไม่ได้ซื้อ (Nej)\"",
    x234: "\"สุดสัปดาห์นี้คุณไม่ต้องทำงานเหรอ?\" → \"ต้องทำสิ ฉันต้องทำงาน (Jo)\" / \"ไม่ ฉันไม่ต้องทำงาน (Nej)\"",
    x235: "\"ฉันเห็นด้วยกับเรื่องนั้นเต็มที่เลย\"",
    x236: "\"คุณพูดถูกทุกอย่างเลย\"",
    x237: "\"ตรงใจฉันเป๊ะเลย!\"",
    x238: "\"ฉันก็คิดแบบเดียวกันเป๊ะเลย\"",
    x239: "\"ฉันเองก็คงพูดได้ไม่ดีไปกว่านี้แล้ว\"",
    x240: "\"เหมือนพูดแทนใจฉันออกมาเลย\"",
    x241: "Mette: \"เฮ้อ เมื่อวานวันอาทิตย์ที่บ้านฉันวุ่นวายสุดๆ เลย...\"",
    x242: "อือฮึ? เกิดอะไรขึ้นเหรอ?",
